defense.vulnerable_config:
// Express - reflects any origin WITH credentials (critical):
app.use((req,res,next)=>{
  res.header('Access-Control-Allow-Origin', req.headers.origin);
  res.header('Access-Control-Allow-Credentials','true');
  next();
});

defense.secure_config:
// Strict allowlist, exact match, no credential+reflection:
const allow = new Set(['https://app.example.com']);
app.use((req,res,next)=>{
  const o = req.headers.origin;
  if (allow.has(o)) {
    res.header('Access-Control-Allow-Origin', o);
    res.header('Access-Control-Allow-Credentials','true');
    res.header('Vary','Origin');
  }
  next();
});
// Reject 'null'; set cookies SameSite=Lax/Strict.
